   100	async function serveStatic(name) {
   101	  const type = TYPES[extname(name)];
   102	  if (name.includes('..') || !type) return { status: 404, type: 'text/plain', body: 'Not found' };
   103	  try {
   104	    return { status: 200, type, body: await readFile(join(PUBLIC_DIR, name), 'utf8') };
   105	  } catch {
   106	    return { status: 404, type: 'text/plain', body: 'Not found' };
   107	  }
   108	}
   109	
   110	if (process.argv[1] === fileURLToPath(import.meta.url)) {
   111	  const { port, dataDir } = loadConfig();
   112	  createServer(async (req, res) => {
   113	    const out = await handle(req.url, { dataDir });
   114	    res.writeHead(out.status, { 'content-type': out.type });
   115	    res.end(out.body);
   116	  }).listen(port, () => console.log(`harbor on http://localhost:${port}`));
   117	}
