     1	// Snapshot times are UTC; showing them in UTC keeps the on-call handoff notes
     2	// and the dashboard in agreement.
     3	export function formatTimestamp(iso) {
     4	  const d = new Date(iso);
     5	  if (Number.isNaN(d.getTime())) return '';
     6	  return `${d.toISOString().slice(0, 10)} ${d.toISOString().slice(11, 16)} UTC`;
